package com.manjul.aikeyboard.tools.packbuild

import java.io.File
import java.sql.Connection
import java.sql.DriverManager

/** The licence rows that every pack carries in `meta` and in the manifest (FR-23 AC2, FR-21 AC3). */
data class PackLicence(val source: String, val name: String, val url: String, val attribution: String)

/** Fixture content written or generated by the team (plan decision 1). */
val TEAM_LICENCE = PackLicence(
    source = "AI Keyboard fixture",
    name = "Apache-2.0",
    url = "https://www.apache.org/licenses/LICENSE-2.0",
    attribution = "AI Keyboard contributors",
)

/**
 * Writes a fresh SQLite file at [out] in one transaction, then `VACUUM`s it, so the same statements always give the
 * same bytes. Any old file at [out] is replaced only after a successful build.
 */
internal fun writeSqlite(out: File, block: (Connection) -> Unit) {
    out.absoluteFile.parentFile.mkdirs()
    val tmp = File(out.absoluteFile.parentFile, out.name + ".tmp")
    tmp.delete()
    try {
        DriverManager.getConnection("jdbc:sqlite:${tmp.absolutePath}").use { c ->
            c.autoCommit = false
            block(c)
            c.commit()
            c.autoCommit = true
            c.createStatement().use { it.execute("VACUUM") }
        }
        check(tmp.renameTo(out) || (out.delete() && tmp.renameTo(out))) { "Cannot move the build to $out" }
    } finally {
        tmp.delete()
        File(tmp.path + "-journal").delete()
    }
}

internal fun Connection.exec(vararg sql: String) = createStatement().use { st -> sql.forEach { st.execute(it) } }

internal fun Connection.insertMeta(rows: List<Pair<String, String>>) {
    prepareStatement("INSERT INTO meta(key, value) VALUES (?, ?)").use { ps ->
        for ((k, v) in rows.sortedBy { it.first }) {
            ps.setString(1, k)
            ps.setString(2, v)
            ps.executeUpdate()
        }
    }
}

internal fun PackLicence.metaRows(): List<Pair<String, String>> =
    listOf("source" to source, "licence_name" to name, "licence_url" to url, "attribution" to attribution)
